CREATE TABLE IF NOT EXISTS guild_local_executions (
    QuestId TEXT NOT NULL CHECK(typeof(QuestId)='text' AND QuestId=upper(QuestId) AND length(QuestId)=36 AND substr(QuestId,9,1)='-' AND substr(QuestId,14,1)='-' AND substr(QuestId,19,1)='-' AND substr(QuestId,24,1)='-' AND length(replace(QuestId,'-',''))=32 AND replace(QuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND QuestId<>'00000000-0000-0000-0000-000000000000'),
    ApprenticeId TEXT NOT NULL CHECK(typeof(ApprenticeId)='text' AND ApprenticeId=upper(ApprenticeId) AND length(ApprenticeId)=36 AND substr(ApprenticeId,9,1)='-' AND substr(ApprenticeId,14,1)='-' AND substr(ApprenticeId,19,1)='-' AND substr(ApprenticeId,24,1)='-' AND length(replace(ApprenticeId,'-',''))=32 AND replace(ApprenticeId,'-','') NOT GLOB '*[^0-9A-F]*' AND ApprenticeId<>'00000000-0000-0000-0000-000000000000'),
    RunId TEXT NOT NULL CHECK(typeof(RunId)='text' AND RunId=upper(RunId) AND length(RunId)=36 AND substr(RunId,9,1)='-' AND substr(RunId,14,1)='-' AND substr(RunId,19,1)='-' AND substr(RunId,24,1)='-' AND length(replace(RunId,'-',''))=32 AND replace(RunId,'-','') NOT GLOB '*[^0-9A-F]*' AND RunId<>'00000000-0000-0000-0000-000000000000'),
    SessionId TEXT NOT NULL CHECK(typeof(SessionId)='text' AND SessionId=upper(SessionId) AND length(SessionId)=36 AND substr(SessionId,9,1)='-' AND substr(SessionId,14,1)='-' AND substr(SessionId,19,1)='-' AND substr(SessionId,24,1)='-' AND length(replace(SessionId,'-',''))=32 AND replace(SessionId,'-','') NOT GLOB '*[^0-9A-F]*' AND SessionId<>'00000000-0000-0000-0000-000000000000'),
    ParentQuestId TEXT NULL CHECK(ParentQuestId IS NULL OR (typeof(ParentQuestId)='text' AND ParentQuestId=upper(ParentQuestId) AND length(ParentQuestId)=36 AND substr(ParentQuestId,9,1)='-' AND substr(ParentQuestId,14,1)='-' AND substr(ParentQuestId,19,1)='-' AND substr(ParentQuestId,24,1)='-' AND length(replace(ParentQuestId,'-',''))=32 AND replace(ParentQuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND ParentQuestId<>'00000000-0000-0000-0000-000000000000')),
    RootQuestId TEXT NOT NULL CHECK(typeof(RootQuestId)='text' AND RootQuestId=upper(RootQuestId) AND length(RootQuestId)=36 AND substr(RootQuestId,9,1)='-' AND substr(RootQuestId,14,1)='-' AND substr(RootQuestId,19,1)='-' AND substr(RootQuestId,24,1)='-' AND length(replace(RootQuestId,'-',''))=32 AND replace(RootQuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND RootQuestId<>'00000000-0000-0000-0000-000000000000'),
    ParentApprenticeId TEXT NULL CHECK(ParentApprenticeId IS NULL OR (typeof(ParentApprenticeId)='text' AND ParentApprenticeId=upper(ParentApprenticeId) AND length(ParentApprenticeId)=36 AND substr(ParentApprenticeId,9,1)='-' AND substr(ParentApprenticeId,14,1)='-' AND substr(ParentApprenticeId,19,1)='-' AND substr(ParentApprenticeId,24,1)='-' AND length(replace(ParentApprenticeId,'-',''))=32 AND replace(ParentApprenticeId,'-','') NOT GLOB '*[^0-9A-F]*' AND ParentApprenticeId<>'00000000-0000-0000-0000-000000000000')),
    InputContentId TEXT NOT NULL CHECK(typeof(InputContentId)='text' AND InputContentId=upper(InputContentId) AND length(InputContentId)=36 AND substr(InputContentId,9,1)='-' AND substr(InputContentId,14,1)='-' AND substr(InputContentId,19,1)='-' AND substr(InputContentId,24,1)='-' AND length(replace(InputContentId,'-',''))=32 AND replace(InputContentId,'-','') NOT GLOB '*[^0-9A-F]*' AND InputContentId<>'00000000-0000-0000-0000-000000000000'),
    InputRevision INTEGER NOT NULL CHECK(typeof(InputRevision)='integer' AND InputRevision=1),
    InputDigest BLOB NOT NULL CHECK(typeof(InputDigest)='blob' AND length(InputDigest)=32),
    InputByteLength INTEGER NOT NULL CHECK(typeof(InputByteLength)='integer' AND InputByteLength BETWEEN 1 AND 65536),
    PRIMARY KEY(QuestId),
    UNIQUE(ApprenticeId),
    UNIQUE(InputContentId),
    CHECK((ParentQuestId IS NULL AND ParentApprenticeId IS NULL AND RootQuestId=QuestId) OR (ParentQuestId IS NOT NULL AND ParentApprenticeId IS NOT NULL AND RootQuestId<>QuestId))
);
